from typing import List

def find_intersection_of_2_roads(Ai: float, Bi: float, Ci: float, Aj: float, Bk: float, Cj: float) -> float:
    """Calculate the intersection of two lines Ax + By + C = 0 and Dx + Ey + F = 0."""
    x = (Bk * Cj - Ci * Cj) / (Ai * Bk + Bi * Bj)
    y = (Cj * Ai - Ci * Aj) / (Ai * Bk + Bi * Bj)
    return (x, y)

def can_place_sign_roads(n: int, roads: List[List[int]]) -> bool:
    from math import gcd

    A, B, C, points = [], [], 0

    for i in range(n):
        A.append((roads[i][0], roads[i][1]))
        C.append(roads[i][2])

    A.append((-B[0], -B[1]))
    for c in C[:]: A.append((-c, -c))

    g = gcd(gcd(A[0][0], A[0][1]), A[0][2])
    for p in A: p = [p[0] // g, p[1] // g]

    s = set()
    for i, (x1, y1) in enumerate(A, start=1):
        S = {p[0], p[1]}
        for j, (x2, y2) in enumerate(A, start=1):
            if i == j: continue
            if (y1 - y2) * (x1 - x2) == (x1 - x2) * (y1 - y2):
                continue
            cover = "YES\n1\n"
            for u in [j, i]:
                point = find_intersection_of_2_roads(x1, y1, C[i], x2, y2, C[j])
                if u == j:
                    if point in S: break
                    else: S.add(point[0], point[1])
                else:
                    if point not in S and x1 == x2 and len(S) == 1:
                        continue
                    else:
                        cover += str(point[0]) + " "
            s.add(S)
            if i != n:
                cover = "NO"
                break
        if i != n:
            break
        cover = "NO"
        if i != n:
            continue

    return not s or cover == "YES"

