from fractions import gcd

def lcm(a, b):
    return a * b // gcd(a, b)

def count_subsequences(T, N, elements):
    mod = 10**9 + 7
    dp = [0] * (N + 1)
    dp[1] = 1  # There's always 1 subsequence of length 1: the element itself

    for i in range(1, N + 1):
        for j in range(i):
            if lcm(elements[i], elements[j]) < elements[i]:
                continue
            for k in range(1, elements[i]):
                if lcm(elements[i], k) > elements[i]:
                    continue
                count = (dp[j] * (k % mod)) % mod
                dp[i] = (dp[i] + count) % mod

    return dp[N]

