import sys
from typing import List

def max_marks(N: int, K: int, chapters: List[List[int]]):
    chapters.sort(key=lambda x: -x[0])  # Sort chapters by weightage in descending order
    memo = [[-1 for _ in range(K + 1)] for _ in range(N + 1)]
    return max_reach(chapters, K, 0, memo)

def max_reach(chapters: List[List[int]], K: int, i: int, memo: List[List[int]]) -> int:
    if i == len(chapters):
        return 0
    if K < chapters[i][1] or memo[i][K] != -1:
        return memo[i][K]  # Cache solution if reused or do not have time
    max_marks = max_reach(chapters, K, i + 1, memo)  # Skip current chapter
    max_marks = max(max_marks, max_reach(chapters, chapters[i][1], i + 1, memo) + chapters[i][0])  # Take current chapter
    memo[i][K] = max_marks
    return max_marks

