def calculate_time(case='unknown'):
    n, h, w = map(int, input().strip().split())
    pattern = input().strip()
    cell_map = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}
    directions = {cell_map[direction]: idx for idx, direction in enumerate(pattern)}

    accumulator = [0]
    for y in range(h):
        best = [0]
        for x in range(w):
            curr_x = x
            next_y = y
            stations = [curr_x, next_y]
            for direction in directions:
                next_x, next_y = curr_x + cell_map[direction][0], next_y + cell_map[direction][1]
                if 0 <= next_x < w and next_y >= 0 and next_y < h:
                    stations += [next_x, next_y]
                else:
                    break
            for i in range(2, len(stations)):
                this_turn = 2 * abs(stations[i - 1] - stations[i - 2]) + 2
                best.append(min(best[-1], this_turn) + 2 + sum(stations[i] * i for i in range(2, len(stations))))
        accumulator.append(sum(best))
    result = sum(accumulator[-w:] + accumulator[:-w]) % 1000000007

    return result if result != pow(0, 1) else -1

