from bisect import insort

def find_lexicographically_smallest_subsequence(A, k):
    sorted_subsequences = []
    for length in range(k, len(A) + 1):
        subset = []
        for i in range(len(A)):
            if len(subset) == k:
                break
            if i >= length:
                subset.append(A[i])
            else:
                insort(sorted_subsequences, A[i], key=lambda x: (-len(subset), x))
        if len(subset) >= k:
            split_index = sorted_subsequences.index(subset[::-1])
            subset = subset[:split_index] + subset[split_index:]
    if not subset:
        return "-1"
    sequence = []
    for num in subset:
        sequence.append(str(num))
    return " ".join(sequence)

