def intersect_lines(r1, r2):
    if r1.A * r2.B == r2.A * r1.B:
        return None  # Lines are parallel
    else:
        A = r2.B - r1.B
        B = r1.A - r2.A
        C = A * r1.C - B * r1.B
        sign = sign(r1.B * r2.A - r1.A * r2.B, r1.A * r2.C - r1.C * r2.A)
        return (-C / A if not sign == 0 else None)

