def shortcut_diameter_minimize(n, k):
    from collections import defaultdict, deque

    # Construct the graph
    graph = defaultdict(list)
    for u, v in zip(range(2, n+1), range(3, n+1)):  # Exclude vk
        graph[u-1].append(v-1)

    # Initialize variables
    all_distances = {v: defaultdict(lambda: float('inf')) for v in range(1, n+1)}
    queue = deque([(1, 0)])
    seen = {1}

    # Level and distance arrays
    level = 0
    distance = defaultdict(lambda: float('inf'))
    levels = defaultdict(lambda: {1})
    distance[1] = 0
    levels[1[len(graph[1]) // 2]].add(1)

    while queue:
        u, dist = queue.popleft()
        levels[dist - 1].add(u)

        for v in graph[u]:
            if v not in seen:
                level += 1
                distance[v] = dist + 1
                all_distances[v][1] = min(all_distances[v][1], dist)
                seen.add(v)
                levels[dist + 1].add(v)
                queue.append((v, dist + 1))

    min_diff = float('inf')
    for key in all_distances:
        if len(levels[key[distance[key]]]) > k:
            min_diff = min(min_diff, key[distance[key]]-key[distance[key]]-all_distances[key[distance[key]]][key[distance[key]]])
        if len(levels[key]) > k:
            min_diff = min(min_diff, key - (n - levels[key][len(graph[key] // 2)]))

    print(2*k - len(levels.keys()))
    for u in levels.keys():
        for v in levels[u]:
            if v >= min(u, k) - u + 1:
