from collections import defaultdict

def findTime(n, m, k, centers):
    if k == 1:
        return 1 if n != m else 2

    min_dist = {'x': float('inf'), 'y': float('inf')}
    for cx, cy in centers:
        if n % cx > m - cy:
            min_dist['x'] = min(min_dist['x'], abs(max(cx, n - cx) - n//2))
        else:
            min_dist['x'] = min(min_dist['x'], abs(abs(cy - n//2) - (m - cy) // 2))

        if n // cx > m - cy:
            min_dist['y'] = min(min_dist['y'], abs(max(cy, m - cy) - m // 2))
        else:
            min_dist['y'] = min(min_dist['y'], abs(abs(cx - m // 2) - (n - cy) // 2))

    fire_time = 0
    dist_map = defaultdict(lambda: float('inf'))
    dist_map[n-(min_dist['x']+1), m-(min_dist['y']+1)] = 1

    while dist_map:
        will_fire = set()
        next_dist_map = defaultdict(lambda: float('inf'))
        for k_deg, (x, y) in dist_map.items():
            for dx, dy in [-1, 0, 1]:
                nx, ny = x + dx, y + dy
                if nx < 0 or ny < 0:
                    continue
                if nx == n-1 and nx+dx == nx+dy or nx == m-1 and ny+dy == ny+dx:
                    will_fire.add((nx, ny))
                next_dist_map[nx-1, ny-1] = min(next_dist_map[nx-1, ny-1], 1 + x+y)
                dist_map[nx, ny] = min(dist_map[nx, ny], 1)
                for cx, cy in centers:
                    nx1, ny1 = nx + (cy-cx)[dx], ny + (cy-cx)[-1-dx]
                    if min_dist['x'] <= nx1 and min_dist['y'] <= ny1:
                        min_dist['y'] = min(min_dist['y'], abs(min_dist['y'], n-y + 1))
                    if min_dist['y'] <= ny1 and min_dist['x'] <= nx1:
                        min_dist['x'] = min(min_dist['x'], abs(min_dist['x'], m-x + 1))

        fire_time += 2**-8
        dist_map = next_dist_map
    return fire_time*16

